param([string]$InstallRoot="$env:ProgramData\Aevrynd\LineGateway")
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Common.ps1');. (Join-Path $PSScriptRoot 'Funnel.Common.ps1');. (Join-Path $PSScriptRoot 'Ngrok.Common.ps1')
$paths=Get-GatewayPaths $InstallRoot;$lock=Enter-PublicTransportLock
try{$executable=Get-NgrokExecutableIdentity $PSScriptRoot;try{Resolve-NgrokPendingLaunch $paths $executable;if(-not(Test-Path $paths.NgrokStateFile)){Write-Output 'Ngrok state is absent.';exit 0};$state=Read-NgrokState $paths;if($null-eq(Get-Process -Id ([int]$state.pid) -ErrorAction SilentlyContinue)){Remove-Item -LiteralPath $paths.NgrokStateFile -Force;Write-Output 'Removed stale Ngrok state for an absent process.';exit 0};$process=Assert-NgrokProcessIdentity $state $executable;$process.Kill($true);$process.WaitForExit()}finally{if($null-ne$executable){$executable.Stream.Dispose()}};Remove-Item $paths.NgrokStateFile -Force;Write-Output 'Ngrok endpoint stopped.'}finally{Exit-PublicTransportLock $lock}
